#include <HBEngine/RayPrograms.hpp>
#include <nlohmann/json.hpp>
#include <iostream>
using Json=nlohmann::json;
int main(){try{Json item={{"key",17},{"instructions",Json::array({{0,0,4,4,-1,-1,-1,-1,0,0,0},{8,-1,4,4,0,-1,-1,-1,0,3,3}})}};auto read=[&](Json value){return hb::gpu::readRayPrograms(Json::array({value})).at(0);};if(read(item).fieldMask!=1023)throw std::runtime_error("Legacy fields changed");item["fields"]={3,9};const auto p=read(item);if(p.fieldMask!=(8|512))throw std::runtime_error("Field mask");const auto source=hb::gpu::rayProgramShader({p});if(source.find("(field<-.5||field==3.0||field==9.0)&&key==17.0")==std::string::npos||source.find("hbRayExecuteFieldTime(-1.0")==std::string::npos||source.find("hbRayExecuteAlphaFieldTime(-1.0")==std::string::npos)throw std::runtime_error("Field dispatch source");int rejected=0;for(const auto& invalid:Json::array({Json(),Json::array(),Json::array({3,3}),Json::array({-1}),Json::array({10}),Json::array({"3"}),Json::array({3.0})})){auto bad=item;bad["fields"]=invalid;try{read(bad);}catch(const std::exception&){rejected++;}}if(rejected!=7)throw std::runtime_error("Invalid fields accepted");auto invalid=p;invalid.fieldMask=0;bool maskRejected=false;try{hb::gpu::validateRayProgram(invalid);}catch(const std::exception&){maskRejected=true;}if(!maskRejected)throw std::runtime_error("Empty mask accepted");std::cout<<Json({{"passed",true},{"legacyMask",1023},{"scopedMask",p.fieldMask},{"invalidRejected",rejected},{"sharedRegularAndAlphaDispatch",true}})<<'\n';}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
